def asset(path): return '/' + path + '?v=' + sha256((ROOT/path).read_bytes()).hexdigest()[:10]
def t(ru, en): return ru if LANG == 'ru' else en
def home(): return '/' if LANG == 'ru' else '/en/'
def case_url(slug): return home() + 'projects/' + slug + '/'
def label(text): return esc(text, quote=True)
def link(url, text, cls='', extra=''): return f'<a href="{url}" class="{cls}" {extra}>{text}</a>'
