def calculator():
 inputs=[('people',t('Пользователей','Users'),10,2000,100,10),('minutes',t('Минут экономии в день','Minutes saved per day'),5,120,20,5),('cost',t('Стоимость часа, ₽','Hourly cost, RUB'),200,5000,1000,100),('adoption',t('Доля использования, %','Adoption rate, %'),10,100,60,5)]
 fields=''.join(f'<div class="calc-field"><div><label for="{k}">{txt}</label><output for="{k}" id="{k}-value">{value}</output></div><input id="{k}" name="{k}" type="range" min="{lo}" max="{hi}" value="{value}" step="{step}"></div>' for k,txt,lo,hi,value,step in inputs)
 return f'''<section class="lab-section" id="lab"><div class="wrap lab-grid"><div><p class="eyebrow">{t('Небольшой эксперимент','A small experiment')} / 01</p><h2>{t('Сколько стоит<br> <em>сэкономленное<br> время?</em>','What is<br> <em>saved time<br> worth?</em>')}</h2><p>{t('Подвигай ползунки и оцени потенциал AI-автоматизации для команды.','Move the sliders to explore the potential of AI automation for a team.')}</p><p class="lab-note">{t('Иллюстративная модель, не расчёт какого-либо из моих проектов.','An illustrative model, not a calculation for any of my projects.')}</p></div><div class="calculator"><div class="calc-heading"><span>{t('Потенциал автоматизации','Automation potential')}</span><span aria-hidden="true">↗</span></div><div class="calc-fields">{fields}</div><div class="calc-result" role="status" aria-live="polite" aria-atomic="true"><span>{t('Стоимость высвобождённого времени за год','Annual value of time freed up')}</span><strong id="calc-result">4,8 <small>{t('млн ₽','M RUB')}</small></strong><p id="calc-hours">{t('4 800 часов в год','4,800 hours per year')}</p></div><details class="calc-method"><summary>{t('Как считается и что не учтено','Method and limitations')}</summary><p>{t('Пользователи × минуты / 60 × стоимость часа × 240 рабочих дней × доля использования.','Users × minutes / 60 × hourly cost × 240 working days × adoption rate.')}</p><p>{t('Это оценка стоимости времени, а не обещанная экономия бюджета. Затраты на внедрение, модели, поддержку и проверку качества не вычтены.','This estimates the value of time, not guaranteed budget savings. Implementation, model, support and quality assurance costs have not been deducted.')}</p></details><noscript><p>{t('Для изменения параметров включите JavaScript.','Enable JavaScript to adjust the inputs.')}</p></noscript></div></div></section>'''
